//! 🎟️ Admission and borrowed caller turns preserve their original ledger without transferring custody.
use semio_framework_job::*;
#[global_allocator]
static HEAP:semio_framework_trace::HeapWitness=semio_framework_trace::HeapWitness;
fn clock()->Option<u64>{Some(1000)}
fn observe<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(value,(heap.requested_bytes,heap.released_bytes))}
#[test]
fn original_payload_authority_admits_once_and_borrowed_contexts_preserve_original_ledger_and_receipts(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let operation=OperationId(99203);let generation=Generation(7);let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:65536,maximum_release_bytes:262144,maximum_depth:64};let demand=JobPayloadAuthority::admission_demand();
 for denied in[RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_capacity_bytes:demand.capacity_bytes-1,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(result,heap)=observe(||JobPayloadAuthority::admit(operation,generation,denied).unwrap());assert!(result.is_none());assert_eq!(heap,(0,0));}
 let((mut authority,birth),heap)=observe(||JobPayloadAuthority::admit(operation,generation,grant).unwrap().unwrap());assert_eq!(heap,(birth.retained_capacity_bytes,birth.released_bytes));assert!(birth.fits(grant));assert_eq!(birth.copied_bytes,demand.copy_bytes);assert_eq!(birth.copied_bytes,law["metadataCopyBytes"].as_u64().unwrap()as usize);let identity=authority.identity();let close=authority.retirement_demands();
 for denied in[RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_release_bytes:close.release_bytes-1,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(step,heap)=observe(||authority.close_step(denied).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(authority.identity(),identity);}
 let(step,heap)=observe(||authority.close_step(grant).unwrap());assert!(matches!(step,RetainedCloneStep::Complete(_)));assert_eq!(heap,(0,birth.retained_capacity_bytes));assert_eq!(step.progress().released_bytes,birth.retained_capacity_bytes);assert_eq!(step.progress().copied_bytes,close.copy_bytes);assert_eq!(observe(||drop(authority)).1,(0,0));
 let stock=RetainedCloneGrant{maximum_items:256,maximum_copy_bytes:65536,..grant};let(mut caller,birth)=observe(||OriginalJobFixtureCaller::admit(operation,generation,stock,clock,1000000,10000));let mut original=None;let binding=caller.original_clock_binding();let fuel=caller.fuel_remaining();
 for turn in 0..17{let(answer,heap)=observe(||caller.turn(grant,|cx|{let identity=cx.payload_authority_identity();if let Some(prior)=original{assert_eq!(identity,prior)}else{original=Some(identity)}assert_eq!(cx.original_clock_binding(),Some(binding));cx.consume_retained(RetainedCloneProgress{copied_bytes:23,..Default::default()})?;assert_eq!(cx.retained_grant().maximum_copy_bytes,grant.maximum_copy_bytes-23);cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:41,..Default::default()})?;cx.consume_fuel(1);assert_eq!(cx.retained_grant().maximum_items,0);assert_eq!(cx.retained_grant().maximum_copy_bytes,grant.maximum_copy_bytes-64);Ok(())}));answer.unwrap();assert_eq!(heap,(0,0));assert_eq!(caller.receipt(),RetainedCloneProgress{copied_items:1,copied_bytes:64,..Default::default()});}
 assert_eq!(caller.fuel_remaining(),fuel-17);let(released,heap)=observe(||caller.retire(stock));assert_eq!(heap,(0,birth.0));assert_eq!(released,birth.0);
}
